class Command(BaseCommand):
    help = "بانک واقعی ۶۷ عامل محیطی سایپا یدک را جایگزین می‌کند."

    def handle(self, *args, **options):
        EnvironmentalFactor.objects.all().delete()
        for r in ROWS:
            EnvironmentalFactor.objects.create(**r)
        self.stdout.write(self.style.SUCCESS(f"{len(ROWS)} عامل محیطی ثبت شد."))
